from pathlib import Path
import re

p=Path('caso001-rev01/index.html')
s=p.read_text()

if 'P2.12D.4 · LOBBY VISUAL' in s:
    raise SystemExit('D4 already applied')

# QR helper is optional. Core room flow must not depend on it.
s=s.replace('<script src="https://cdn.jsdelivr.net/npm/@supabase/supabase-js@2.116.0"></script>', '<script src="https://cdn.jsdelivr.net/npm/@supabase/supabase-js@2.116.0"></script>\n<script src="https://cdnjs.cloudflare.com/ajax/libs/qrcodejs/1.0.0/qrcode.min.js" defer></script>', 1)

css=r'''
/* P2.12D.4 · LOBBY VISUAL + QR + WHATSAPP */
.roomHead{position:relative;margin:20px 0 14px;padding:18px 20px;border:1px solid #5c442d;background:linear-gradient(110deg,#17120e,#0b0a09 58%,#160c0a);box-shadow:0 14px 35px rgba(0,0,0,.28);overflow:hidden}.roomHead:after{content:"SALA DE INVESTIGACIÓN";position:absolute;right:18px;bottom:-3px;color:rgba(190,145,81,.055);font:900 34px/1 Impact,'Arial Narrow',sans-serif;letter-spacing:.05em;pointer-events:none}.roomHead .muted{font-size:9px;letter-spacing:.2em;font-weight:950;color:#99836a}.roomHead .code{font-size:clamp(36px,7vw,66px);line-height:.95;margin-top:5px;color:#e9bf73}.roomHead .meta{justify-content:flex-end;position:relative;z-index:2}.lobbyCasePanel{padding:0;overflow:hidden;border-radius:8px;border-color:#65492f}.lobbyHeader{display:flex;justify-content:space-between;gap:18px;align-items:center;padding:18px 20px;border-bottom:1px solid #503923;background:linear-gradient(180deg,#1a1511,#100e0c)}.lobbyEyebrow{font-size:9px;letter-spacing:.2em;font-weight:950;color:#a98659}.lobbyHeader h2{font-family:Georgia,serif;font-size:28px;margin:4px 0 3px}.lobbyHeader p{margin:0;color:#aa9a88;font-size:12px}.lobbySeal{border:3px solid #842520;color:#c74339;padding:8px 10px;transform:rotate(-4deg);font-size:10px;line-height:1.12;text-align:center;font-weight:950;letter-spacing:.12em}.lobbyLayout{display:grid;grid-template-columns:minmax(0,1.55fr) minmax(270px,.45fr);min-height:420px}.lobbyRoster{padding:18px 20px 20px}.players.lobbyPlayers{grid-template-columns:repeat(3,minmax(0,1fr));gap:10px}.lobbyPerson{position:relative;display:grid;grid-template-columns:76px 1fr;min-height:108px;border:1px solid #4f3a29;background:#0e0d0c;overflow:hidden;box-shadow:0 8px 18px rgba(0,0,0,.2)}.lobbyPerson.human{border-color:#745137;border-left:4px solid #992c27}.lobbyPerson.npc{border-style:dashed;opacity:.74}.lobbyPortrait{position:relative;overflow:hidden;background:#12100e;border-right:1px solid #4e3928}.lobbyPortrait img{width:100%;height:100%;min-height:108px;object-fit:cover;object-position:center 24%;display:block;filter:sepia(.1) saturate(.88) contrast(1.04)}.lobbyPerson.npc .lobbyPortrait img{filter:grayscale(.75) sepia(.18) brightness(.7);opacity:.72}.lobbyPortrait:after{content:"";position:absolute;inset:0;background:linear-gradient(180deg,transparent 42%,rgba(0,0,0,.55));pointer-events:none}.lobbyPersonCopy{padding:11px 10px;display:flex;flex-direction:column;justify-content:center;min-width:0}.lobbyPersonCopy b{font-family:Georgia,serif;font-size:18px;color:#eee0cd}.lobbyPersonCopy .playerName{font-size:11px;color:#c2ae96;margin-top:4px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.lobbyPersonCopy .playerRole{font-size:8px;color:#8d7b67;letter-spacing:.08em;margin-top:5px}.lobbyBadge{display:inline-flex;width:max-content;margin-top:8px;border:1px solid #4e654d;background:#101710;color:#9bc39b;padding:3px 5px;font-size:7px;font-weight:950;letter-spacing:.1em}.lobbyBadge.host{border-color:#89642f;background:#1d150c;color:#efca7b}.lobbyBadge.npc{border-color:#51483d;background:#11100f;color:#8e8173}.hostPin{position:absolute;right:5px;top:5px;background:#8a251f;color:#fff0dc;border:1px solid #ba443a;padding:3px 5px;font-size:7px;font-weight:950;letter-spacing:.08em}.lobbyNoteBox{margin-top:13px;border-left:3px solid #7f5d36;background:#15110d;padding:10px 12px;color:#b7a591!important;font-size:12px;line-height:1.5}.inviteDossier{position:relative;border-left:1px solid #5b422c;background:linear-gradient(145deg,#d7c09b,#b28d63);color:#211911;padding:19px;display:flex;flex-direction:column;align-items:center;text-align:center;overflow:hidden}.inviteDossier:after{content:"INVITACIÓN";position:absolute;right:-22px;bottom:25px;border:3px solid rgba(125,31,28,.35);color:rgba(125,31,28,.4);padding:6px 10px;transform:rotate(-10deg);font-size:14px;font-weight:950;letter-spacing:.13em}.inviteLabel{font-size:8px;letter-spacing:.2em;color:#70231f;font-weight:950}.inviteDossier h3{font-family:Georgia,serif;font-size:22px;margin:5px 0 5px}.inviteDossier p{font-size:11px;line-height:1.45;margin:0;color:#4c3929;max-width:235px}.qrFrame{position:relative;width:196px;height:196px;margin:15px auto 11px;padding:8px;background:#efe0c4;border:1px solid #705439;box-shadow:7px 8px 0 rgba(60,39,22,.14);display:grid;place-items:center}.qrBox{width:180px;height:180px;display:grid;place-items:center;overflow:hidden}.qrBox canvas,.qrBox img{width:180px!important;height:180px!important;display:block}.qrFallback{width:180px;height:180px;display:grid;place-items:center;border:2px dashed #6d5439;color:#6b241f;font-size:10px;line-height:1.5;padding:15px}.inviteCode{font:900 23px/1 ui-monospace,SFMono-Regular,Menlo,monospace;letter-spacing:.12em;color:#6b241f;margin:6px 0}.inviteHint{font-size:9px;color:#67503b;letter-spacing:.04em}.lobbyActions{width:100%;display:grid;grid-template-columns:1fr 1fr;gap:7px;margin-top:15px;position:relative;z-index:2}.lobbyActions .btn{min-height:42px;font-size:11px;padding:9px}.lobbyActions .btn.primary{grid-column:1/-1}.lobbyActions .btn.whatsapp{border-color:#3c694a;background:#122219;color:#b8e5c4}.lobbyStats{display:flex;gap:7px;flex-wrap:wrap;margin:12px 0 2px}.lobbyStats span{border:1px solid #4f3c2c;background:#15110e;padding:6px 8px;font-size:9px;letter-spacing:.08em;color:#c9b394}.lobbyStats .ready{border-color:#375d42;color:#a6d7ae}.lobbyStats .pending{border-color:#70552c;color:#e1c27c}
@media(max-width:980px){.lobbyLayout{grid-template-columns:1fr}.inviteDossier{border-left:0;border-top:1px solid #5b422c}.players.lobbyPlayers{grid-template-columns:repeat(2,minmax(0,1fr))}.inviteDossier{display:grid;grid-template-columns:220px 1fr;gap:18px;text-align:left;align-items:center}.inviteCopy{text-align:left}.qrFrame{grid-row:1/4;margin:0}.lobbyActions{grid-column:2}.inviteDossier:after{display:none}}
@media(max-width:650px){.roomHead{display:grid;padding:14px}.roomHead .meta{justify-content:flex-start}.roomHead:after{display:none}.lobbyHeader{align-items:flex-start}.lobbyHeader h2{font-size:23px}.players.lobbyPlayers{grid-template-columns:1fr}.lobbyPerson{grid-template-columns:84px 1fr}.inviteDossier{display:flex;text-align:center}.inviteCopy{text-align:center}.qrFrame{margin:14px auto 10px}.lobbyActions{grid-template-columns:1fr}.lobbyActions .btn.primary{grid-column:auto}.lobbyRoster{padding:14px}.lobbyHeader{padding:15px}.lobbySeal{font-size:8px}.inviteDossier{padding:16px}}
'''
anchor='/* P2.12D.3 · CHARACTER DOSSIERS */'
if anchor not in s:
    raise SystemExit('D3 CSS anchor missing')
s=s.replace(anchor,css+'\n'+anchor,1)

old_html='''  <section id="lobby" class="panel"><h2 style="margin-top:0">Sala de investigación</h2><div id="players" class="players"></div><div id="lobbyNote" class="muted" style="margin-top:10px"></div><div id="lobbyControls" class="toolbar"></div></section>'''
new_html='''  <section id="lobby" class="panel lobbyCasePanel">
    <div class="lobbyHeader"><div><div class="lobbyEyebrow">EXPEDIENTES · CASO 001 · SALA PREVIA</div><h2>Mesa de investigación</h2><p>Asignación de personajes y acceso del equipo.</p></div><div class="lobbySeal">SALA<br>ABIERTA</div></div>
    <div class="lobbyLayout">
      <div class="lobbyRoster"><div id="lobbyStats" class="lobbyStats"></div><div id="players" class="players lobbyPlayers"></div><div id="lobbyNote" class="muted lobbyNoteBox"></div></div>
      <aside class="inviteDossier"><div class="qrFrame"><div id="qrBox" class="qrBox" aria-label="Código QR para ingresar a la sala"></div></div><div class="inviteCopy"><div class="inviteLabel">INVITAR INVESTIGADOR</div><h3>Escaneá para entrar</h3><p>El enlace carga automáticamente este código de sala. Cada jugador elige después un personaje disponible.</p><div id="inviteCode" class="inviteCode">—</div><div class="inviteHint">También podés compartir por WhatsApp o copiar el enlace.</div></div><div id="lobbyControls" class="lobbyActions"></div></aside>
    </div>
  </section>'''
if old_html not in s:
    raise SystemExit('lobby HTML anchor not found')
s=s.replace(old_html,new_html,1)

pattern=r"function renderLobby\(\)\{[\s\S]*?\}\nfunction evidenceEvents"
m=re.search(pattern,s)
if not m:
    raise SystemExit('renderLobby function not found')
new_js=r'''function roomInviteUrl(code){const u=new URL(window.location.href);u.search='';u.hash='';u.searchParams.set('room',String(code||'').trim().toUpperCase());return u.toString()}
function renderLobbyQr(url,code){const el=$('#qrBox');if(!el)return;el.innerHTML='';try{if(typeof window.QRCode==='function'){new window.QRCode(el,{text:url,width:180,height:180,colorDark:'#17110e',colorLight:'#efe0c4',correctLevel:window.QRCode.CorrectLevel.M});return}}catch(e){console.warn('QR unavailable',e)}el.innerHTML=`<div class="qrFallback"><div><b>QR NO DISPONIBLE</b><br>Usá el código<br><strong>${esc(code||'—')}</strong><br>o “Copiar enlace”.</div></div>`}
function renderLobby(){
 const room=view?.room||{},players=view?.players||[],humanByChar=new Map(players.map(p=>[Number(p.character_index),p]));
 const code=String(room.code||'').trim().toUpperCase(),inviteUrl=code?roomInviteUrl(code):'';
 $('#code').textContent=code||'—';$('#inviteCode').textContent=code||'—';
 const statusLabel=room.status==='waiting'?'ESPERANDO':room.status==='active'?'EN CURSO':room.status==='finished'?'FINALIZADO':String(room.status||'—').toUpperCase();
 $('#roomMeta').innerHTML=`<span class="pill gold">${room.mode==='imp'?'IMPOSTOR':'NORMAL'}</span><span class="pill ${room.status==='waiting'?'warn':'good'}">${esc(statusLabel)}</span><span class="pill">${players.length}/6 HUMANOS</span>`;
 const npcCount=Math.max(0,6-players.length),ready=players.length>=3;
 $('#lobbyStats').innerHTML=`<span>${players.length} INVESTIGADOR${players.length===1?'':'ES'} HUMANO${players.length===1?'':'S'}</span><span>${npcCount} NPC</span><span class="${ready?'ready':'pending'}">${ready?'✓ EQUIPO LISTO':'FALTAN '+Math.max(0,3-players.length)+' HUMANO'+(Math.max(0,3-players.length)===1?'':'S')}</span>`;
 $('#players').innerHTML=P2_LABELS.characters.map((name,i)=>{const p=humanByChar.get(i),img=REV01_PORTRAITS[i],profile=REV01_PROFILES[i];return p?`<article class="lobbyPerson human"><div class="lobbyPortrait"><img src="${esc(img)}" alt="Retrato de ${esc(name)}"></div><div class="lobbyPersonCopy"><b>${esc(name)}</b><span class="playerName">${esc(p.display_name)}</span><span class="playerRole">${esc(profile)}</span><span class="lobbyBadge ${p.is_host?'host':''}">${p.is_host?'ANFITRIÓN · HOST':'JUGADOR CONECTADO'}</span></div>${p.is_host?'<span class="hostPin">HOST</span>':''}</article>`:`<article class="lobbyPerson npc"><div class="lobbyPortrait"><img src="${esc(img)}" alt="Retrato de ${esc(name)}"></div><div class="lobbyPersonCopy"><b>${esc(name)}</b><span class="playerName">PERSONAJE SIN JUGADOR</span><span class="playerRole">${esc(profile)}</span><span class="lobbyBadge npc">NPC AUTOMÁTICO</span></div></article>`}).join('');
 $('#lobbyNote').textContent=room.status==='waiting'?(players.length<3?'Para abrir el expediente hacen falta al menos 3 jugadores humanos. Los personajes restantes serán controlados como NPC.':'El equipo mínimo está completo. El HOST puede abrir el expediente cuando todos estén listos.'):'La partida ya comenzó; los jugadores existentes pueden reingresar con el mismo navegador/sesión.';
 let buttons='';if(view?.is_host&&room.status==='waiting')buttons+=`<button class="btn primary" id="startGame" ${players.length<3?'disabled':''}>ABRIR EXPEDIENTE</button>`;buttons+=`<button class="btn whatsapp" id="shareWhatsApp">WHATSAPP</button><button class="btn" id="copyInviteLink">COPIAR ENLACE</button><button class="btn" id="copyCode">COPIAR CÓDIGO</button>`;$('#lobbyControls').innerHTML=buttons;
 renderLobbyQr(inviteUrl,code);
 $('#shareWhatsApp')?.addEventListener('click',()=>{if(!code)return;const text=`🔎 EXPEDIENTES · Caso 001 — La Última Reunión\n\nEntrá a nuestra sala de investigación:\n${inviteUrl}\n\nCódigo de sala: ${code}\n\nPoné tu nombre, elegí un personaje libre y tocá “Unirme a la sala”.`;window.open('https://wa.me/?text='+encodeURIComponent(text),'_blank','noopener')});
 $('#copyInviteLink')?.addEventListener('click',async()=>{if(!inviteUrl)return;try{await navigator.clipboard.writeText(inviteUrl);toast('Enlace de sala copiado.')}catch{toast(inviteUrl)}});
 $('#copyCode')?.addEventListener('click',async()=>{try{await navigator.clipboard.writeText(code);toast('Código copiado.')}catch{toast(`Código: ${code}`)}});
 $('#startGame')?.addEventListener('click',()=>doAction(async()=>{await adapter.startGame();await refresh(true)},'Partida iniciada.'));
 $('#lobby').classList.toggle('hidden',room.status!=='waiting')
}
function evidenceEvents'''
s=s[:m.start()]+new_js+s[m.end():]

p.write_text(s)
print('P2.12D.4 patch applied')
